-- 1. Mise à niveau de stock_batches : ajout de purchase_price et synchronisation avec les produits
ALTER TABLE `stock_batches` 
  ADD COLUMN `purchase_price` decimal(10,2) NOT NULL DEFAULT 0.00 AFTER `remaining_qty`;

UPDATE `stock_batches` sb 
JOIN `products` p ON sb.`product_id` = p.`id` 
SET sb.`purchase_price` = p.`purchase_price`
WHERE sb.`purchase_price` = 0.00 OR sb.`purchase_price` IS NULL;

-- 2. Mise à niveau de sales : ajout de paid_at et invoice_number
ALTER TABLE `sales` 
  ADD COLUMN `paid_at` timestamp NULL DEFAULT NULL AFTER `payment_status`,
  ADD COLUMN `invoice_number` varchar(50) DEFAULT NULL AFTER `points_redeemed`;

-- Remplir paid_at pour toutes les ventes déjà réglées ('Paid')
UPDATE `sales` 
SET `paid_at` = `date` 
WHERE `payment_status` = 'Paid' AND `paid_at` IS NULL;

-- Générer le numéro de facture conforme (ex: BL-2026-0001 ou BV-2026-0001)
UPDATE `sales` 
SET `invoice_number` = CONCAT(IFNULL(`invoice_type`, 'BV'), '-', YEAR(`date`), '-', LPAD(`id`, 4, '0')) 
WHERE `invoice_number` IS NULL OR `invoice_number` = '';

-- 3. Création de la table sale_payments (gestion des règlements et créances)
DROP TABLE IF EXISTS `sale_payments`;
CREATE TABLE `sale_payments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_id` int(11) NOT NULL,
  `customer_payment_id` int(11) DEFAULT NULL,
  `amount` decimal(10,2) NOT NULL,
  `payment_method` enum('Cash','Card','Bank Transfer','Cheque','Insurance') DEFAULT 'Cash',
  `notes` text DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `sale_id` (`sale_id`),
  KEY `customer_payment_id` (`customer_payment_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `sale_payments_ibfk_1` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sale_payments_ibfk_2` FOREIGN KEY (`customer_payment_id`) REFERENCES `customer_payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sale_payments_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 4. Initialisation des paiements initiaux dans sale_payments pour les ventes existantes
INSERT INTO `sale_payments` (`sale_id`, `customer_payment_id`, `amount`, `payment_method`, `notes`, `user_id`, `created_at`)
SELECT s.`id`, NULL, s.`paid_amount`, s.`payment_method`, 'Paiement initial comptoir', s.`user_id`, s.`date`
FROM `sales` s
WHERE s.`paid_amount` > 0 
  AND NOT EXISTS (SELECT 1 FROM `sale_payments` sp WHERE sp.`sale_id` = s.`id`);

